import type {CallspecDocument, JsonSchema} from '../callspecDocument';
import {
    assertGeneratableSchema,
    sanitizeMethodName,
    schemaToTypes,
    typeNameForRoute,
} from './schemaToTypeScript';

const GENERATED_HEADER = `/**
 * Generated by callspec — do not edit manually.
 * Regenerate with: npx callspec generate-client <callspec.json> --output <file>
 */`;

export function generateClientSource(
    document: CallspecDocument,
    options?: {className?: string},
): string {

    const className = options?.className ?? 'ApiClient';
    const routeNames = Object.keys(document.routes).sort((a, b) => a.localeCompare(b));
    const typeBlocks: string[] = [];
    const methods: string[] = [];
    const usedMethodNames = new Set<string>();

    for (const routeName of routeNames) {

        const route = document.routes[routeName];

        assertGeneratableSchema(route.input, `Route "${routeName}" input`);
        assertGeneratableSchema(route.output, `Route "${routeName}" output`);

        const inputTypeName = typeNameForRoute(routeName, 'Input');
        const outputTypeName = typeNameForRoute(routeName, 'Output');
        const inputTypes = schemaToTypes(route.input, inputTypeName);
        const outputTypes = schemaToTypes(route.output, outputTypeName);

        for (const generated of [...inputTypes.types, ...outputTypes.types]) {

            if (!typeBlocks.some((block) => block.includes(`export type ${generated.name}`))) {

                typeBlocks.push(generated.definition);

            }

        }

        if (route.errors) {

            const errorMembers: string[] = [];

            for (const [code, def] of Object.entries(route.errors).sort(([a], [b]) => a.localeCompare(b))) {

                const wireSchema = def.schema;
                const properties = wireSchema?.properties as Record<string, JsonSchema> | undefined;
                const required = wireSchema?.required as string[] | undefined;
                const dataSchema = required?.includes('data') ? properties?.data : undefined;

                if (dataSchema) {

                    assertGeneratableSchema(dataSchema, `Route "${routeName}" error "${code}" data`);
                    const dataTypeName = typeNameForRoute(routeName, `${code}ErrorData`);
                    const dataTypes = schemaToTypes(dataSchema, dataTypeName);

                    for (const generated of dataTypes.types) {

                        if (!typeBlocks.some((block) => block.includes(`export type ${generated.name}`))) {

                            typeBlocks.push(generated.definition);

                        }

                    }

                    errorMembers.push(`{ error: ${JSON.stringify(code)}; data: ${dataTypeName} }`);

                } else {

                    errorMembers.push(`{ error: ${JSON.stringify(code)} }`);

                }

            }

            if (errorMembers.length) {

                const errorResponseTypeName = typeNameForRoute(routeName, 'ErrorResponse');

                typeBlocks.push(
                    `export type ${errorResponseTypeName} = ${errorMembers.join(' | ')};`,
                );

            }

        }

        let methodName = sanitizeMethodName(routeName);

        while (usedMethodNames.has(methodName)) {

            methodName = sanitizeMethodName(`${routeName}_${methodName}`);

        }

        usedMethodNames.add(methodName);

        methods.push(`
    async ${methodName}(input: ${inputTypeName}): Promise<${outputTypeName}> {
        return this.runtime.call(${JSON.stringify(routeName)}, input);
    }`);

    }

    return [
        GENERATED_HEADER,
        '',
        `import {CallspecClient, type CallspecClientConfig} from 'callspec/client';`,
        '',
        'export type ApiClientConfig = CallspecClientConfig;',
        '',
        ...typeBlocks,
        '',
        `export class ${className} {`,
        '    private readonly runtime: CallspecClient;',
        '',
        `    constructor(config: ApiClientConfig) {`,
        '        this.runtime = new CallspecClient(config);',
        '    }',
        ...methods,
        '}',
        '',
    ].join('\n');

}
